// Reduce a failed execution to what an administrator needs, without copying
// user content or credentials into an email.
const data = $input.first().json || {};
const error = data.execution && data.execution.error ? data.execution.error : (data.error || {});
const message = String(error.message || "unknown error").slice(0, 400)
  .replace(/([?&](token|key|secret|password)=)[^&\s]+/gi, "$1[redacted]")
  .replace(/https?:\/\/[^\s"']+/g, "[url]");
return [{
  json: {
    workflow: (data.workflow && data.workflow.name) || "unknown workflow",
    executionId: data.execution && data.execution.id ? String(data.execution.id) : "unknown",
    lastNode: (data.execution && data.execution.lastNodeExecuted) || "unknown",
    message,
    at: new Date().toISOString(),
  },
}];
